window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-701fb0a27ec0efc3"]={"versions": [{"id": "FIG-701fb0a27ec0efc3", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm (<code>act E2E_P02Protect()</code>) zur Spezifikation des Kontroll- und Datenflusses innerhalb der Funktion <code>E2E_P02Protect()</code> der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library, Profil 2). Es definiert die standardisierte Sender-Schutzsequenz für zu übertragende Nutzdaten über ein unsicheres Kommunikationsmedium.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionsschnittstelle:</strong> <code>E2E_P02Protect(Config, State, Data)</code> mit Konfigurationszeiger <code>Config</code>, Zustandsstruktur <code>State</code> und Nutzdatenarray <code>Data</code>.\n</li><li><strong>Eingangs- und Zustandsparameter:</strong>\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: 4-Bit-Sequenzzähler im Zustandsdatenblock.\n</li><li><code>Config-&gt;DataIDList</code>: Konfiguriertes Daten-ID-Array zur Auswahl der zählerabhängigen Daten-ID (<code>DataID</code>).\n</li><li><code>Config-&gt;DataLength</code>: Gesamtlänge der Daten in Bits.\n</li><li><code>Data</code>: Byte-Array der Nutzdaten (<code>Data[0]</code>, <code>Data[1]</code>, ..., <code>Data[Config-&gt;DataLength/8-1]</code>).\n</li></ul>\n</li><li><strong>Hilfsfunktion &amp; Ergebnisgrößen:</strong>\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8H2F()</code>: Berechnungsroutine für CRC8H2F-Prüfsumme.\n</li><li>Lokale Variablen <code>DataID</code> und <code>CRC</code>.\n</li></ul>\n</li><li><strong>Kommentar-Annotationen:</strong> Deskriptive Notizen zur Zählerplatzierung in <code>Data[1]</code> (Bits 0...3) und zur CRC-Platzierung in <code>Data[0]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Aufruf der Funktion <code>E2E_P02Protect(Config, State, Data)</code> am Initialknoten.\n</li><li><strong>Zählerinkrementierung:</strong> Inkrementieren von <code>State-&gt;Counter</code> (als aufrufende Aktion/Subaktivität gekennzeichnet).\n</li><li><strong>Zählerschreiben:</strong> Einfügen des 4-Bit-Zählers in die unteren 4 Bits von Byte 1: <code>*(Data+1) = (*(Data+1) &amp; 0xF0) | (State-&gt;Counter &amp; 0x0F)</code>. Die oberen 4 Bits bleiben maskiert erhalten.\n</li><li><strong>DataID-Ermittlung:</strong> Zählerabhängiges Auslesen der DataID aus der Konfigurationstabelle: <code>DataID = Config-&gt;DataIDList[State-&gt;Counter]</code>.\n</li><li><strong>CRC-Berechnung:</strong> Ausführen von <code>Crc_CalculateCRC8H2F()</code> über den Datenbereich ab Byte 1 bis zum letzten Datenbyte (<code>Data[1]</code>, <code>Data[2]</code>, …, <code>Data[Config-&gt;DataLength/8-1]</code>) gefolgt von <code>DataID</code>.\n</li><li><strong>CRC-Speicherung:</strong> Zuweisung der berechneten Prüfsumme in das erste Byte: <code>Data[0] = CRC</code>.\n</li><li><strong>Abschluss:</strong> Rückkehr aus der Funktion (<code>return</code>) am Aktivitätsendknoten.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der E2E-Profil-2-Datenschutzberechnung für Software-Komponenten und BSW-Module. Implementierer müssen exakt die vorgegebene Reihenfolge einhalten: Erst den Zähler aktualisieren und serialisieren, danach die zugehörige zählerspezifische Data-ID bestimmen, die CRC8H2F-Berechnung einschließlich Data-ID durchführen und abschließend die Prüfsumme an Offset 0 eintragen. Bitmaskierung und Array-Offsets sind strikt einzuhalten.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d0d785aa652b7f9b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontroll- und Datenflusses für die Profil-2-Schutzfunktion <code>E2E_P02Protect()</code> der AUTOSAR E2E-Bibliothek (End-to-End Communication Protection Library). Es definiert die standardisierte Sender-Schutzsequenz für zu übertragende Nutzdaten über ein unsicheres Kommunikationsmedium.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Funktionsschnittstelle:</strong> <code>E2E_P02Protect(Config, State, Data)</code> mit Konfigurationszeiger <code>Config</code>, Zustandsstruktur <code>State</code> und Nutzdatenarray <code>Data</code>.\n</li><li><strong>Eingangs- und Zustandsparameter:</strong>\n<ul class=\"fig-list\"><li><code>State-&gt;Counter</code>: 4-Bit-Sequenzzähler im Zustandsdatenblock.\n</li><li><code>Config-&gt;DataIDList</code>: Konfiguriertes Daten-ID-Array zur Auswahl der zählerabhängigen Daten-ID (<code>DataID</code>).\n</li><li><code>Config-&gt;DataLength</code>: Gesamtlänge der Daten in Bits.\n</li><li><code>Data</code>: Byte-Array der Nutzdaten (<code>Data[0]</code>, <code>Data[1]</code>, ..., <code>Data[Config-&gt;DataLength/8-1]</code>).\n</li></ul>\n</li><li><strong>Hilfsfunktion &amp; Ergebnisgrößen:</strong>\n<ul class=\"fig-list\"><li><code>Crc_CalculateCRC8H2F()</code>: Berechnungsroutine für CRC8H2F-Prüfsumme.\n</li><li>Lokale Variablen <code>DataID</code> und <code>CRC</code>.\n</li></ul>\n</li><li><strong>Kommentar-Annotationen:</strong> Deskriptive Notizen zur Zählerplatzierung in <code>Data[1]</code> (Bits 0...3) und zur CRC-Platzierung in <code>Data[0]</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Start:</strong> Eintritt über den Initialknoten.\n</li><li><strong>Zählerinkrementierung:</strong> Inkrementieren von <code>State-&gt;Counter</code> (als aufrufende Aktion/Subaktivität gekennzeichnet).\n</li><li><strong>Zählerschreiben:</strong> Einfügen des 4-Bit-Zählers in die unteren 4 Bits von Byte 1: <code>*(Data+1) = (*(Data+1) &amp; 0xF0) | (State-&gt;Counter &amp; 0x0F)</code>. Die oberen 4 Bits bleiben maskiert erhalten.\n</li><li><strong>DataID-Ermittlung:</strong> Zählerabhängiges Auslesen der DataID aus der Konfigurationstabelle: <code>DataID = Config-&gt;DataIDList[State-&gt;Counter]</code>.\n</li><li><strong>CRC-Berechnung:</strong> Ausführen von <code>Crc_CalculateCRC8H2F()</code> über den Datenbereich ab Byte 1 bis zum letzten Datenbyte (<code>Data[1]</code>, <code>Data[2]</code>, …, <code>Data[Config-&gt;DataLength/8-1]</code>) gefolgt von <code>DataID</code>.\n</li><li><strong>CRC-Speicherung:</strong> Zuweisung der berechneten Prüfsumme in das erste Byte: <code>Data[0] = CRC</code>.\n</li><li><strong>Abschluss:</strong> Erreichen des Aktivitätsendknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation der E2E-Profil-2-Datenschutzberechnung für Software-Komponenten und BSW-Module. Implementierer müssen exakt die vorgegebene Reihenfolge einhalten: Erst den Zähler aktualisieren und serialisieren, danach die zugehörige zählerspezifische Data-ID bestimmen, die CRC8H2F-Berechnung einschließlich Data-ID durchführen und abschließend die Prüfsumme an Offset 0 eintragen. Bitmaskierung und Array-Offsets sind strikt einzuhalten.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-701fb0a27ec0efc3", "to": "FIG-d0d785aa652b7f9b", "fr": "R3.2.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>UML-Aktivitätsrahmen (<code>act E2E_P02Protect()</code>) und umgebender Diagrammrahmen entfernt.\n</li><li>Textbeschriftung am Initialknoten (<code>E2E_P02Protect(Config, State, Data)</code>) am oberen Bildrand abgeschnitten / entfernt.\n</li><li>Textbeschriftung <code>return</code> am Aktivitätsendknoten entfernt.\n</li></ul>"}]};
